package com.ia.project.dynamicstudyplanner.ga.tactical.repair;

import com.ia.project.dynamicstudyplanner.domain.tactical.TacticalStudyPlan;
import com.ia.project.dynamicstudyplanner.ga.EvolutionContext;

/**
 * Interface for repairing invalid chromosomes generated by the operators.
 * This is the cornerstone of a Repair-Based Operator paradigm.
 */
public interface ChromosomeRepairer {
    /**
     * Inspects a TacticalStudyPlan and deterministically resolves any constraint violations
     * (e.g., fatigue accumulation, missing mandatory reviews).
     *
     * @param plan The potentially invalid plan.
     * @param context Context containing constraints and student state.
     * @return A valid, repaired plan.
     */
    TacticalStudyPlan repair(TacticalStudyPlan plan, EvolutionContext context);
}
